"""
NABBAH — حزمة المحركات في ملف واحد (بديل عن مجلدات phase21 / phase22 / phase23 / phase24 / phase25 / phase26 / phase27 / phase28 / phase29 / phase210 / phase211).
ضعه بجانب main.py. عند استيراده تُسجَّل كل المحركات (25) فتعمل: import scenario_engine / sales_engine ...
نفس ملفات المجلدات حرفياً، مضمّنة بترميز base64. لا منطق جديد هنا.
المجلدات للتطوير والاختبارات فقط، وهذا الملف وحده يكفي للتشغيل على الخادم.
"""
import base64
import sys
import types

_MODULES = [
    ("nabbah_finance", ""),
    ("nabbah_trust", ""),
    ("period_aggregation", ""),
    ("legacy_adapters", ""),
    ("semantic_layer", ""),
    ("kpi_engine", ""),
    ("analysis_engines", ""),
    ("ai_gateway", ""),
    ("rule_catalog", ""),
    ("forecast_engine", ""),
    ("intelligence_engine", ""),
    ("decision_memory", ""),
    ("scenario_engine", ""),
    ("platform_bridge", ""),
    ("canonical_model", ""),
    ("period_model", ""),
    ("metric_registry", ""),
    ("ingestion", ""),
    ("sales_engine", ""),
    ("inventory_engine", ""),
    ("purchases_engine", ""),
    ("cashflow_engine", ""),
    ("hr_engine", ""),
    ("ops_engine", ""),
    ("finance_engine", ""),
]

_loaded = []
for _name, _b64 in _MODULES:
    if _name in sys.modules:
        _loaded.append(_name)
        continue
    _mod = types.ModuleType(_name)
    _mod.__file__ = f"<nabbah_engines:{_name}>"
    sys.modules[_name] = _mod
    try:
        exec(compile(base64.b64decode(_b64).decode("utf-8"), _mod.__file__, "exec"), _mod.__dict__)
        _loaded.append(_name)
    except Exception:
        del sys.modules[_name]
        raise

LOADED = tuple(_loaded)
